// Clears output on every failure. Inputs are bounded and never mutated.
inline Status Integrate(const Vec4* points,unsigned int pointCount,const Triangle* triangles,unsigned int triangleCount,float mass,Result* output,unsigned int maxPoints=100000,unsigned int maxTriangles=200000){
 if(!output)return InvalidInput;
 unsigned char* bytes=(unsigned char*)output;for(unsigned int i=0;i<sizeof(Result);i++)bytes[i]=0;
 if(!Finite(mass)||mass<=0)return InvalidMass;
 if(!points||!triangles||!pointCount||!triangleCount||pointCount>maxPoints||triangleCount>maxTriangles||pointCount>1000000||triangleCount>2000000)return InvalidInput;
 for(unsigned int i=0;i<pointCount;i++)if(!Finite(points[i].x)||!Finite(points[i].y)||!Finite(points[i].z)||!Finite(points[i].w))return InvalidInput;
 for(unsigned int i=0;i<triangleCount;i++)if(triangles[i].a>=pointCount||triangles[i].b>=pointCount||triangles[i].c>=pointCount)return InvalidInput;
#if defined(_MSC_VER) && defined(_M_IX86)
 Geometry geometry={points,pointCount,0x80000000u|pointCount,triangles,triangleCount,0x80000000u|triangleCount};
 Detail::State state={};Result result={};
 unsigned int status=Detail::Raw(&geometry,mass,&result,&state);
 const unsigned int offsets[]={0,4,16,20,24,32,36,40,48,52,56,64,68,72};
 for(unsigned int i=0;i<14;i++)if(!Finite(*(float*)((unsigned char*)&result+offsets[i])))return NonfiniteResult;
 if(status)return (Status)status;
 // Original scratch padding is unspecified; never expose stack contents.
 result.pad0=result.pad1=result.center.w=0;result.inertia[3]=result.inertia[7]=result.inertia[11]=0;
 *output=result;return Ok;
#else
 return UnsupportedPlatform;
#endif
}
